import itertools, heapq
def best_count(tasks):
    for k in range(len(tasks), -1, -1):
        for c in itertools.combinations(tasks, k):
            t = 0; ok = True
            for d, dl in sorted(c, key=lambda x: x[1]):
                t += d
                if t > dl: ok = False; break
            if ok: return k
def rule(tasks):
    heap = []; t = 0; dropped = []
    for d, dl in sorted(tasks, key=lambda x: x[1]):
        heapq.heappush(heap, -d); t += d
        if t > dl: x = -heapq.heappop(heap); t -= x; dropped.append(x)
    return len(heap), dropped
T = [(3, 3), (2, 4), (2, 5), (1, 6)]
def trade(prices):
    best = {0: 0}
    for p in prices:
        nxt = {}
        for h, m in best.items():
            for h2, m2 in ((h, m), (h + 1, m - p), (h - 1, m + p)):
                if h2 >= 0 and m2 > nxt.get(h2, -10 ** 9): nxt[h2] = m2
        best = nxt
    return best[0]
def gen(n): return [(1 + (7 * i) % 5, 3 + (11 * i) % 17) for i in range(n)]
result = best_count(T)

